<?php require __DIR__.'/inc/header.php';$title='Reviews Moderation';$pdo=db();if(is_post()){verify_csrf();$id=(int)post('id');$status=(string)post('status','pending');$pdo->prepare('UPDATE reviews SET status=? WHERE id=?')->execute([$status,$id]);flash('success','Review moderated.');redirect('/admin/reviews.php');}$rows=$pdo->query('SELECT r.*,p.name product_name,u.name user_name FROM reviews r JOIN products p ON p.id=r.product_id LEFT JOIN users u ON u.id=r.user_id ORDER BY r.id DESC')->fetchAll();?><div class="bg-white border rounded-2xl overflow-hidden soft"><div class="p-5 font-black">Reviews</div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Product</th><th class="p-3 text-left">Reviewer</th><th class="p-3 text-left">Rating</th><th class="p-3 text-left">Review</th><th class="p-3 text-left">Moderation</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t"><td class="p-3 font-bold"><?=e($r['product_name'])?></td><td class="p-3"><?=e($r['user_name']??'Guest')?></td><td class="p-3 text-amber-500"><?=str_repeat('★',(int)$r['rating'])?></td><td class="p-3 max-w-md"><?=e($r['review'])?></td><td class="p-3"><form method="post" class="flex gap-2"><?=csrf_input()?><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="rounded-lg border-slate-200 text-xs"><option <?=$r['status']==='1'?'selected':''?> value="1">Approved</option><option <?=$r['status']==='0'?'selected':''?> value="0">Hidden</option><option <?=$r['status']==='pending'?'selected':''?> value="pending">Pending</option></select><button class="px-3 py-2 rounded-lg bg-slate-950 text-white text-xs font-bold">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/inc/footer.php'; ?>
